def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    valid_mask = remaining >= 0
    if not np.any(valid_mask):
        return np.full_like(bins, -np.inf, dtype=float)

    utilization = 1.0 - (remaining / (bins + 1e-8))
    utilization_score = utilization ** 3 - utilization ** 2
    slack_penalty = np.tanh(remaining)

    return np.where(valid_mask, utilization_score - 0.5 * slack_penalty, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    valid = remaining >= 0
    if not np.any(valid):
        return np.full_like(bins, -np.inf, dtype=float)
    mean_rem = np.mean(remaining[valid])
    variance_penalty = np.where(valid, -np.cos((remaining - mean_rem) / (np.std(remaining[valid]) + 1e-8)), 0.0)
    efficiency = np.where(valid, 1.0 / (1.0 + np.exp(remaining)), 0.0)
    return np.where(valid, efficiency + 0.2 * variance_penalty, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining < 0, -np.inf, 1.0 / (1.0 + remaining ** 2) + remaining / bins)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    valid = remaining >= 0
    if not np.any(valid):
        return np.full_like(bins, -np.inf, dtype=float)
    mean_rem = np.mean(remaining[valid])
    std_rem = np.std(remaining[valid])
    spread = std_rem if std_rem > 0 else 1.0
    scores = np.where(valid, -remaining - np.abs(remaining - mean_rem) / spread, -np.inf)
    return scores

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining < 0, -np.inf, -remaining)
